import{_ as a,H as r,f as t,i as l}from"./chunks/framework.BH2BK_3i.js";const d=JSON.parse('{"title":"加餐2｜后两章课后题答案","description":"","frontmatter":{},"headers":[{"level":2,"title":"中级篇 打造工单辅助系统","slug":"中级篇-打造工单辅助系统","link":"#中级篇-打造工单辅助系统","children":[{"level":3,"title":"第15节课","slug":"第15节课","link":"#第15节课","children":[]},{"level":3,"title":"第16节课","slug":"第16节课","link":"#第16节课","children":[]},{"level":3,"title":"第17节课","slug":"第17节课","link":"#第17节课","children":[]},{"level":3,"title":"第18节课","slug":"第18节课","link":"#第18节课","children":[]}]},{"level":2,"title":"马拉松 持续改造RAG应用","slug":"马拉松-持续改造rag应用","link":"#马拉松-持续改造rag应用","children":[{"level":3,"title":"第20节课","slug":"第20节课","link":"#第20节课","children":[]},{"level":3,"title":"第22节课","slug":"第22节课","link":"#第22节课","children":[]},{"level":3,"title":"第23节课","slug":"第23节课","link":"#第23节课","children":[]}]}],"relativePath":"RAG系统实战课/加餐2｜后两章课后题答案.md","filePath":"RAG系统实战课/加餐2｜后两章课后题答案.md","lastUpdated":1779816165000}'),n={name:"RAG系统实战课/加餐2｜后两章课后题答案.md"};function i(o,e,h,p,g,c){return r(),t("div",null,[...e[0]||(e[0]=[l('<h1 id="加餐2-后两章课后题答案" tabindex="-1">加餐2｜后两章课后题答案 <a class="header-anchor" href="#加餐2-后两章课后题答案" aria-label="Permalink to &quot;加餐2｜后两章课后题答案&quot;">​</a></h1><p>你好，我是叶伟民。</p><p>到今天为止，课程后两章的内容即将更新完毕。和之前一样，这次加餐我会把后两章的思考题答集中发布，供你参考。</p><h2 id="中级篇-打造工单辅助系统" tabindex="-1">中级篇 打造工单辅助系统 <a class="header-anchor" href="#中级篇-打造工单辅助系统" aria-label="Permalink to &quot;中级篇 打造工单辅助系统&quot;">​</a></h2><h3 id="第15节课" tabindex="-1"><a href="https://time.geekbang.org/column/article/813934" target="_blank" rel="noreferrer">第15节课</a> <a class="header-anchor" href="#第15节课" aria-label="Permalink to &quot;[第15节课](https://time.geekbang.org/column/article/813934)&quot;">​</a></h3><p>Q：即使在中文里面，同一个事物在不同的方言里面也有不同的叫法，如何解决这个问题呢？</p><p>A：我们可以使用某个嵌入模型再加上该方言对应的数据进行微调，得出该方言的嵌入模型。如前文所述，微调和RAG并不冲突，可以一起结合使用。</p><h3 id="第16节课" tabindex="-1"><a href="https://time.geekbang.org/column/article/814486" target="_blank" rel="noreferrer">第16节课</a> <a class="header-anchor" href="#第16节课" aria-label="Permalink to &quot;[第16节课](https://time.geekbang.org/column/article/814486)&quot;">​</a></h3><p>Q1：增删改查数据的时候，为什么不直接选择 LangChain 里提供的 pgvector API，而是使用 SQL 语句完成呢？</p><p>A1：因为前面提到，工具选择上我曾经从FAISS换成Milvus和PostgreSQL，其中一个很重要的原因就是FAISS没有提供图形化管理工具来管理，操作起来很不方便。</p><p>为此，我不得不在Jupyter里面使用LangChain来操作FAISS的数据。如果使用LangChain对应pgvector的API来增删改查数据，那我仍然要再Jupyter里使用LangChain来操作pgvector，那意义何在？</p><p>而使用SQL语句来增删改查数据，就可以在图形化管理工具pgadmin里面直接进行测试，这样方便很多。我的口号是——能用图形化界面解决的，就不要用代码。</p><p>Q2：既然换一个嵌入模型就需要全部重新计算一遍向量编码，为什么要添加嵌入模型列，直接更新所有向量编码列的值不就好了吗？</p><p>A2：更新所有向量编码列的值耗时很长，中途只要有任何原因中断，你就不知道哪一行已经更新过，哪一行还没有更新，这时候就需要通过嵌入模型列的值来判断了。</p><h3 id="第17节课" tabindex="-1"><a href="https://time.geekbang.org/column/article/815540" target="_blank" rel="noreferrer">第17节课</a> <a class="header-anchor" href="#第17节课" aria-label="Permalink to &quot;[第17节课](https://time.geekbang.org/column/article/815540)&quot;">​</a></h3><p>Q：计算两个向量之间距离其实不止以上四种，但是为什么只列出以上四种呢？</p><p>A：理论不能脱离实际。以上四种普遍都有配套的工具支持，我们马上就可以拿来用，不需要我们从零开始编写计算代码。例如pgvector目前就只支持这四种算法。例如前面讲到的LangChain不支持负内积，那就需要自己编写计算代码。</p><h3 id="第18节课" tabindex="-1"><a href="https://time.geekbang.org/column/article/815860" target="_blank" rel="noreferrer">第18节课</a> <a class="header-anchor" href="#第18节课" aria-label="Permalink to &quot;[第18节课](https://time.geekbang.org/column/article/815860)&quot;">​</a></h3><p>Q：今天这节课里，我们并没有将查询参数的向量编码保存进数据库。那么是否有必要将查询参数的向量编码保存进数据库呢？如果有必要，这么做的意义是什么呢？</p><p>A：不是必要的。但是可以将查询参数的向量编码保存进数据库，这样有助于事后调试和诊断以改进检索准确性。</p><p>另外，这一章的第14和19节课思考题都是开放性问题，你可以开开脑洞，在留言区里分享你的思考。</p><h2 id="马拉松-持续改造rag应用" tabindex="-1">马拉松 持续改造RAG应用 <a class="header-anchor" href="#马拉松-持续改造rag应用" aria-label="Permalink to &quot;马拉松 持续改造RAG应用&quot;">​</a></h2><h3 id="第20节课" tabindex="-1"><a href="https://time.geekbang.org/column/article/817424" target="_blank" rel="noreferrer">第20节课</a> <a class="header-anchor" href="#第20节课" aria-label="Permalink to &quot;[第20节课](https://time.geekbang.org/column/article/817424)&quot;">​</a></h3><p>Q：Ragas实现了这么多指标，我们是否全部都需要关心呢？</p><p>A：不需要，我们只需要根据自己的实际业务关心所需要的指标即可。</p><h3 id="第22节课" tabindex="-1"><a href="https://time.geekbang.org/column/article/818511" target="_blank" rel="noreferrer">第22节课</a> <a class="header-anchor" href="#第22节课" aria-label="Permalink to &quot;[第22节课](https://time.geekbang.org/column/article/818511)&quot;">​</a></h3><p>Q：当一个RAG框架是用其他编程语言实现的，例如C#的时候，你如何取长补短？</p><p>A：可以使用AI分析和解释它的代码，甚至可以用AI将它的代码改成Python代码。</p><h3 id="第23节课" tabindex="-1"><a href="https://time.geekbang.org/column/article/819241" target="_blank" rel="noreferrer">第23节课</a> <a class="header-anchor" href="#第23节课" aria-label="Permalink to &quot;[第23节课](https://time.geekbang.org/column/article/819241)&quot;">​</a></h3><p>Q：如果要对实战案例1应用GraphRAG，应该如何整理出实体和关系，请讲出你的思路。</p><p>A：可以根据实际业务关系将关系数据库里面的某些字段视为实体来源，某些字段视为关系来源。</p><p>同样，21和24节课的题目也是开放性的，所以没有提供参考答案。</p><p>以上就是这次加餐的全部内容。希望课程的课后题可以帮你加深对RAG的理解，如果有什么思考或者疑问也可以继续在留言区里和我交流讨论。</p>',33)])])}const u=a(n,[["render",i]]);export{d as __pageData,u as default};
